package com.xyz.question_bank_management_system.modules.agent.service.impl;
import com.fasterxml.jackson.databind.ObjectMapper;import com.xyz.question_bank_management_system.config.CorrelationContext;import com.xyz.question_bank_management_system.exception.*;import com.xyz.question_bank_management_system.modules.agent.entity.*;import com.xyz.question_bank_management_system.modules.agent.mapper.PersonalizedResourceMapper;import com.xyz.question_bank_management_system.modules.agent.service.ResourceUnitService;import com.xyz.question_bank_management_system.modules.knowledge.entity.*;import com.xyz.question_bank_management_system.modules.knowledge.mapper.*;import com.xyz.question_bank_management_system.modules.knowledge.repository.Neo4jKnowledgeGraphRepository;import com.xyz.question_bank_management_system.modules.learning.entity.*;import com.xyz.question_bank_management_system.modules.learning.mapper.LearningPathV1Mapper;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @RequiredArgsConstructor public class ResourceUnitServiceImpl implements ResourceUnitService {private final LearningPathV1Mapper pathMapper;private final PersonalizedResourceMapper mapper;private final KnowledgeGraphVersionMapper versionMapper;private final KnowledgePointMapper pointMapper;private final Neo4jKnowledgeGraphRepository graph;private final ObjectMapper objectMapper;
 @Override @Transactional public ResourceUnit aggregate(String pathCode,String startCode){LearningPath p=pathMapper.selectByCode(pathCode);if(p==null)throw BizException.of(ErrorCode.NOT_FOUND,"路径不存在");LearningPathVersion v=pathMapper.selectActiveVersion(p.getId());List<LearningPathItem> steps=pathMapper.selectSteps(v.getId());int start=0;if(startCode==null){for(LearningPathItem step:steps){if(!"LEARNING".equals(step.getStage()))continue;ResourceUnit reused=mapper.selectUnitByVersionAndStep(v.getId(),step.getId());if(reused!=null&&"READY".equals(reused.getStatus()))return reused;}}if(startCode!=null){start=-1;for(int i=0;i<steps.size();i++)if(startCode.equals(steps.get(i).getPathStepCode())){start=i;break;}if(start<0)throw BizException.of(ErrorCode.FAILED_INPUT,"pathStepId 不属于当前路径版本");ResourceUnit reused=mapper.selectUnitByVersionAndStep(v.getId(),steps.get(start).getId());if(reused!=null)return reused;}Set<Long> consumed=mapper.selectConsumedSteps(v.getId()).stream().map(ResourceUnitStep::getPathStepId).collect(java.util.stream.Collectors.toSet());if(startCode==null)while(start<steps.size()&&consumed.contains(steps.get(start).getId()))start++;if(start>=steps.size())throw BizException.of(ErrorCode.CONFLICT,"当前路径没有可聚合步骤");KnowledgeGraphVersion gv=versionMapper.selectActive(p.getCourseId());if(gv==null||!graph.available())throw BizException.of(ErrorCode.KNOWLEDGE_GRAPH_UNAVAILABLE,"知识图谱不可用，不能聚合 ResourceUnit");List<LearningPathItem> selected=new ArrayList<>();List<Map<String,Object>> evidence=new ArrayList<>();for(int i=start;i<steps.size()&&selected.size()<5;i++){LearningPathItem step=steps.get(i);if(consumed.contains(step.getId())||!"LEARNING".equals(step.getStage()))break;if(!selected.isEmpty()){LearningPathItem prev=selected.get(selected.size()-1);KnowledgePoint a=pointMapper.selectById(prev.getKnowledgePointId()),b=pointMapper.selectById(step.getKnowledgePointId());if(a!=null&&b!=null&&!Objects.equals(a.getChapterId(),b.getChapterId()))break;if(!graph.hasAllowedRelation(p.getCourseId(),gv.getVersionCode(),prev.getKnowledgePointId(),step.getKnowledgePointId()))break;evidence.add(Map.of("source","KG","from",prev.getKnowledgePointId(),"to",step.getKnowledgePointId(),"graphVersion",gv.getVersionCode()));}selected.add(step);}if(selected.isEmpty())throw BizException.of(ErrorCode.FAILED_INPUT,"无法形成 ResourceUnit");try{ResourceUnit unit=new ResourceUnit();unit.setResourceUnitCode("ru_"+UUID.randomUUID().toString().replace("-",""));unit.setCourseId(p.getCourseId());unit.setPathId(p.getId());unit.setPathVersionId(v.getId());unit.setStatus("READY");unit.setAggregationEvidenceJson(objectMapper.writeValueAsString(evidence));unit.setCorrelationId(CorrelationContext.get());mapper.insertUnit(unit);List<ResourceUnitStep> rows=new ArrayList<>();for(LearningPathItem x:selected){ResourceUnitStep r=new ResourceUnitStep();r.setResourceUnitId(unit.getId());r.setPathStepId(x.getId());r.setOrderNo(x.getOrderNo());rows.add(r);}mapper.batchInsertUnitSteps(rows);return unit;}catch(Exception ex){if(ex instanceof RuntimeException r)throw r;throw new IllegalStateException(ex);}}
}
